"""Independent bounded checks; no provider, signing, funding or settlement."""
from copy import deepcopy
from dataclasses import asdict, replace
from datetime import datetime, timedelta
import pytest
import modules.foundups.simulator.economics.circuit_breaker as bm
from modules.foundups.simulator.economics.cabr_flow_router import CABRFlowInputs, route_cabr_ups_flow
from modules.foundups.simulator.economics.circuit_breaker import BreakerState, BreakerTrigger, CircuitBreaker


@pytest.fixture
def clock(monkeypatch):
    class Clock(datetime):
        current = datetime(2026, 10, 31, 8)
        @classmethod
        def now(cls):
            return cls.current
    monkeypatch.setattr(bm, "datetime", Clock)
    return Clock


def test_integer_score_saturation_preserves_default_release():
    result = route_cabr_ups_flow(CABRFlowInputs(1000, 7, True, 9000))
    assert result.valve_open is True and result.cabr_pipe_size == 1.0
    assert result.epoch_release_budget_ups == result.routed_ups == 20.0
    assert result.treasury_ups_before == 1000.0 and result.treasury_ups_after == 980.0
    closed = route_cabr_ups_flow(CABRFlowInputs(1000, 7, False, 9000))
    assert closed.valve_open is False and closed.epoch_release_budget_ups == 20.0
    assert closed.routed_ups == 0.0 and closed.treasury_ups_after == 1000.0


def test_numeric_subclasses_and_bool_coercion_never_execute():
    class IntTrap(int):
        def __float__(self):
            pytest.fail("int subclass coercion executed")
        def __lt__(self, other):
            pytest.fail("int subclass comparison executed")
    class FloatTrap(float):
        def __float__(self):
            pytest.fail("float subclass coercion executed")
        def __lt__(self, other):
            pytest.fail("float subclass comparison executed")
    class BoolTrap:
        def __bool__(self):
            pytest.fail("PoB truth coercion executed")
    original = CABRFlowInputs(1000, 1, False, 100)
    for name in ("treasury_ups_available", "cabr_pipe_size", "requested_ups", "release_rate"):
        for value in (IntTrap(1), FloatTrap(1.0)):
            with pytest.raises(ValueError):
                route_cabr_ups_flow(replace(original, **{name: value}))
    with pytest.raises(ValueError):
        route_cabr_ups_flow(replace(original, pob_validated=BoolTrap()))


def test_closed_valve_still_rejects_invalid_quantities():
    original = CABRFlowInputs(1000, 1, False, 100)
    for name in ("treasury_ups_available", "cabr_pipe_size", "requested_ups", "release_rate"):
        for value in (float("nan"), float("-inf"), 10**400):
            with pytest.raises(ValueError):
                route_cabr_ups_flow(replace(original, **{name: value}))


def test_invalid_metric_cannot_unfreeze_expired_emergency(clock):
    breaker = CircuitBreaker()
    assert breaker.check_conditions(0.4, 100000.0) is BreakerState.EMERGENCY
    clock.current += timedelta(hours=48)
    for field in ("daily_outflow", "btc_price_24h_ago"):
        previous = getattr(breaker, field)
        setattr(breaker, field, float("inf"))
        before = deepcopy(asdict(breaker))
        with pytest.raises(ValueError):
            breaker.check_conditions(1.0, 100000.0)
        assert asdict(breaker) == before and breaker.exits_blocked()
        setattr(breaker, field, previous)


def test_crash_and_outflow_severity_at_exact_threshold(clock):
    restricted = CircuitBreaker(daily_outflow=0.11)
    assert restricted.check_conditions(0.85, 70000.0) is BreakerState.RESTRICTED
    assert restricted.trigger is BreakerTrigger.OUTFLOW_HIGH
    emergency = CircuitBreaker(daily_outflow=0.11)
    assert emergency.check_conditions(0.4, 60000.0) is BreakerState.EMERGENCY
    assert emergency.trigger is BreakerTrigger.BTC_CRASH


def test_queue_remains_held_across_repeated_healthy_polls(clock):
    breaker = CircuitBreaker()
    breaker.check_conditions(0.4, 100000.0)
    exit_request = breaker.queue_exit("fixture_owner", "fixture_foundup", 1.0)
    before = deepcopy(asdict(breaker))
    clock.current += timedelta(hours=48)
    for _ in range(3):
        assert breaker.check_conditions(1.0, 100000.0) is BreakerState.EMERGENCY
        assert breaker.process_queue() == []
        assert breaker.exit_queue == [exit_request]
        assert asdict(breaker) == before
        clock.current += timedelta(hours=24)
